import ast
from pathlib import Path
root=Path('/Users/doob/dev/energy_forecast_ws/766bd5/project/runs/766bd5/code')
for path in sorted(root.glob('*.py')):
    tree=ast.parse(path.read_text())
    parents={}
    for n in ast.walk(tree):
        for c in ast.iter_child_nodes(n): parents[c]=n
    for n in ast.walk(tree):
        if isinstance(n, ast.Assign) and any(isinstance(p,(ast.FunctionDef,ast.AsyncFunctionDef)) for p in iter(lambda:None,None)):
            pass
    def visit_fn(fn):
        for n in ast.walk(fn):
            if n is fn: continue
            # don't descend nested defs
            p=parents.get(n)
            nested=False
            while p is not None and p is not fn:
                if isinstance(p,(ast.FunctionDef,ast.AsyncFunctionDef,ast.Lambda)):
                    nested=True; break
                p=parents.get(p)
            if nested: continue
            if isinstance(n, ast.Assign):
                names=[]
                for t in n.targets:
                    if isinstance(t, ast.Name): names.append(t.id)
                if names:
                    print(f'{path.name}:{n.lineno}:{fn.name}: {", ".join(names)}')
    for n in tree.body:
        if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef)):
            visit_fn(n)
        elif isinstance(n,ast.ClassDef):
            for m in n.body:
                if isinstance(m,(ast.FunctionDef,ast.AsyncFunctionDef)): visit_fn(m)
